const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
  HeadingLevel, PageBreak, VerticalAlign
} = require('/home/claude/.npm-global/lib/node_modules/docx');
const fs = require('fs');

// ── COLOR PALETTE ──────────────────────────────────────────────────────────
const ROSE_GOLD   = "B76E79";
const SOFT_BLUSH  = "F5E6E8";
const LIGHT_ROSE  = "FAF0F1";
const DARK_TEXT   = "2C2C2C";
const MID_GRAY    = "555555";
const LIGHT_GRAY  = "DDDDDD";
const WHITE       = "FFFFFF";
const ACCENT_TAN  = "F0E6DC";
const ACCENT_GOLD = "C9A96E";

// ── HELPERS ────────────────────────────────────────────────────────────────
const border = (color = LIGHT_GRAY) => ({ style: BorderStyle.SINGLE, size: 1, color });
const borders = (color = LIGHT_GRAY) => ({ top: border(color), bottom: border(color), left: border(color), right: border(color) });
const noBorder = () => ({ style: BorderStyle.NONE, size: 0, color: "FFFFFF" });
const noBorders = () => ({ top: noBorder(), bottom: noBorder(), left: noBorder(), right: noBorder() });

function spacer(pts = 80) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: pts } });
}

function sectionDivider(color = ROSE_GOLD) {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color, space: 1 } },
    spacing: { before: 40, after: 200 }
  });
}

function sectionTitle(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 28, color: ROSE_GOLD, font: "Arial" })],
    spacing: { before: 360, after: 120 }
  });
}

function stepHeader(number, title) {
  return new Paragraph({
    children: [
      new TextRun({ text: number + "  ", bold: true, size: 26, color: ROSE_GOLD, font: "Arial" }),
      new TextRun({ text: title, bold: true, size: 26, color: DARK_TEXT, font: "Arial" }),
    ],
    spacing: { before: 300, after: 80 }
  });
}

function labelText(text, color = MID_GRAY) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 20, color, font: "Arial", allCaps: true })],
    spacing: { before: 160, after: 60 }
  });
}

function scriptLine(text, color = DARK_TEXT) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color, font: "Arial", italics: true })],
    spacing: { before: 40, after: 40 },
    indent: { left: 360 }
  });
}

function tip(text) {
  return new Paragraph({
    children: [new TextRun({ text: "TIP: " + text, size: 20, color: ACCENT_GOLD, font: "Arial", bold: true })],
    spacing: { before: 80, after: 40 },
    indent: { left: 360 }
  });
}

function questionItem(q, ref = "bullets") {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children: [new TextRun({ text: q, size: 22, color: DARK_TEXT, font: "Arial" })],
    spacing: { before: 40, after: 40 }
  });
}

function bodyText(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color: MID_GRAY, font: "Arial" })],
    spacing: { before: 40, after: 60 },
    indent: { left: 360 }
  });
}

function shadeBox(children, fill = SOFT_BLUSH) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: borders(ROSE_GOLD),
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill, type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 200, right: 200 },
            children
          })
        ]
      })
    ]
  });
}

function accentBox(children, fill = ACCENT_TAN) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: borders(ACCENT_GOLD),
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill, type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 200, right: 200 },
            children
          })
        ]
      })
    ]
  });
}

function twoColTable(leftContent, rightContent, leftWidth = 4680, rightWidth = 4680) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [leftWidth, rightWidth],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders(),
            width: { size: leftWidth, type: WidthType.DXA },
            margins: { top: 80, bottom: 80, left: 0, right: 120 },
            children: leftContent
          }),
          new TableCell({
            borders: noBorders(),
            width: { size: rightWidth, type: WidthType.DXA },
            margins: { top: 80, bottom: 80, left: 120, right: 0 },
            children: rightContent
          })
        ]
      })
    ]
  });
}

// ── DOCUMENT ───────────────────────────────────────────────────────────────
const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u25BA",
          alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } }, run: { color: ROSE_GOLD, size: 18 } }
        }]
      },
      {
        reference: "checklist",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u25A1",
          alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } }, run: { color: ROSE_GOLD, size: 20 } }
        }]
      }
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: DARK_TEXT } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [

      // ══════════════════════════════════════════════════════════════════════
      // COVER / TITLE
      // ══════════════════════════════════════════════════════════════════════
      new Paragraph({
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 22, color: ROSE_GOLD, font: "Arial", allCaps: true, characterSpacing: 100 })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 480, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Discovery Call Sales Script", bold: true, size: 48, color: DARK_TEXT, font: "Arial" })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Your step-by-step guide to diagnosing, connecting, and closing", size: 22, color: MID_GRAY, font: "Arial", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 60 }
      }),
      sectionDivider(),

      // ══════════════════════════════════════════════════════════════════════
      // HOW TO USE THIS SCRIPT
      // ══════════════════════════════════════════════════════════════════════
      shadeBox([
        new Paragraph({
          children: [new TextRun({ text: "How to Use This Script", bold: true, size: 24, color: ROSE_GOLD, font: "Arial" })],
          spacing: { before: 0, after: 80 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "Italicized lines are YOUR words. Bullet points are questions to choose from. You do not need to ask every question. Read the room, pick what fits, and keep the energy conversational. The goal is to make the prospect feel heard, not interviewed.", size: 22, color: MID_GRAY, font: "Arial" })],
          spacing: { before: 0, after: 0 }
        })
      ]),
      spacer(80),

      // ══════════════════════════════════════════════════════════════════════
      // STAGE 1: RAPPORT
      // ══════════════════════════════════════════════════════════════════════
      sectionTitle("STAGE 1: OPEN THE CALL"),
      stepHeader("01", "Rapport (30 seconds max)"),

      labelText("Say this:"),
      scriptLine('"Hey [Name], how\'s your week going so far?"'),
      scriptLine('"Nice. And where are you calling in from today?"'),
      scriptLine('"Perfect. Alright, let\'s jump in."'),
      tip("Keep it short. Move on quickly. You build real rapport through expertise, not small talk."),
      spacer(60),

      // ══════════════════════════════════════════════════════════════════════
      // STAGE 2: FRAME
      // ══════════════════════════════════════════════════════════════════════
      stepHeader("02", "Set the Frame (Authority + Safety)"),
      labelText("Say this:"),
      scriptLine('"So here\'s what I want to do. I\'ve reviewed everything you shared before the call, so I already have a solid picture of your business and where things might be breaking down. But I have a few deeper questions I want to walk through with you."'),
      spacer(20),
      scriptLine('"My goal on this call is simple: figure out if we can actually help you. If it looks like a fit, I\'ll walk you through exactly what a partnership looks like, the numbers, and the expected ROI. And if for some reason it does not make sense, I\'ll be very direct about that and point you somewhere better."'),
      spacer(20),
      scriptLine('"Sound fair?"'),
      tip("Wait for a yes before continuing. This sets the frame that you are the doctor, not the salesperson."),
      spacer(60),

      // ══════════════════════════════════════════════════════════════════════
      // STAGE 3: PAIN OPENER
      // ══════════════════════════════════════════════════════════════════════
      stepHeader("03", "Pain Opener"),
      labelText("Say this:"),
      scriptLine('"Cool. So like I said, I have seen the notes, but I want to hear it directly from you."'),
      scriptLine('"What is going on in your business right now that made you reach out for help?"'),
      tip("Shut up after this question. Let them talk. This is the most important answer on the call."),

      spacer(80),
      sectionDivider(),

      // ══════════════════════════════════════════════════════════════════════
      // STAGE 4: DISCOVERY
      // ══════════════════════════════════════════════════════════════════════
      sectionTitle("STAGE 2: DISCOVERY (11 CORE AREAS)"),
      new Paragraph({
        children: [new TextRun({ text: "Work through these areas in order. You do not need every question. Pick 2 to 3 that feel most relevant based on what they share. Always follow up before moving on.", size: 22, color: MID_GRAY, font: "Arial", italics: true })],
        spacing: { before: 0, after: 160 }
      }),

      // 1. PAIN
      stepHeader("01", "Pain: Anchor the Emotion"),
      bodyText("Goal: Get them to articulate the real problem and how long it has been happening. Emotion drives decisions."),
      questionItem('"When you say you are stuck, what does that actually look like month to month?"'),
      questionItem('"How long has this been going on?"'),
      questionItem('"If this has been an issue for over a year, why now? What changed?"'),
      questionItem('"Be honest with me: how frustrating is it to know you are doing everything right clinically, but the business still is not working?"'),
      questionItem('"If nothing changes, where do you realistically see this business in 12 months?"'),
      spacer(40),

      // 2. TIMING
      stepHeader("02", "Timing: Create Urgency Without Pressure"),
      bodyText("Goal: Understand why they are ready now and whether they will actually move forward today."),
      questionItem('"If you did solve this, when would you want that to happen?"'),
      questionItem('"Why not six months from now?"'),
      questionItem('"Was there a moment recently where you thought, I cannot keep doing this the same way?"'),
      questionItem('"Is today the day you finally decide to fix the foundation instead of trying another band-aid?"'),
      spacer(40),

      // 3. FINANCES
      stepHeader("03", "Finances: Establish the Baseline"),
      bodyText("Goal: Understand their revenue reality so you can show a clear ROI. These numbers also let you reference industry benchmarks."),
      questionItem('"Roughly, what did the business bring in last month in revenue?"'),
      questionItem('"And profit-wise, what actually made it to you after expenses?"'),
      questionItem('"How much are you currently spending on marketing or outside agencies?"'),
      questionItem('"Does that spend feel controlled and predictable, or stressful and unclear?"'),
      questionItem('"If we could show you how to double the return on money you are already spending, would that be worth prioritizing?"'),
      spacer(40),

      accentBox([
        new Paragraph({
          children: [new TextRun({ text: "Industry Financial Benchmarks to Reference", bold: true, size: 22, color: DARK_TEXT, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "Use these to show you understand med spa financials at a deep level:", size: 22, color: MID_GRAY, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Average client visit value: $350 to $600", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Annual client value (repeat visits): $1,800 to $5,000+", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Healthy marketing spend: 8 to 12% of gross revenue", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Membership conversion benchmark: 20 to 30% of active client base", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Device utilization target: 70%+ booked hours per week", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Client retention rate (healthy): 65 to 80%", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        spacer(60),
        new Paragraph({
          children: [new TextRun({ text: "Ad Spend ROI Comparison", bold: true, size: 22, color: DARK_TEXT, font: "Arial" })],
          spacing: { before: 60, after: 80 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "When a prospect pushes back on marketing spend, use this to reframe:", size: 22, color: MID_GRAY, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Stock market average return: 8 to 10% annually", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Real estate average return: 8 to 12% annually", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Well-managed Meta/Google ad spend for med spas: 5 to 10X return", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({
          children: [new TextRun({ text: "Example: $2,000/month in ad spend generating $14,000 in new client revenue is a 7X return. No stock or bond does that.", size: 22, color: ACCENT_GOLD, font: "Arial", bold: true, italics: true })],
          spacing: { before: 100, after: 40 },
          indent: { left: 360 }
        })
      ]),
      spacer(80),

      // 4. PARTNER
      stepHeader("04", "Partner: Decision Control"),
      bodyText("Goal: Identify who else is in the room so you are not surprised at the end."),
      questionItem('"Do you make these decisions on your own, or does a partner or spouse need to be involved?"'),
      questionItem('"If we decided this makes sense today, would anyone else need to sign off?"'),
      spacer(40),

      // 5. CURRENT SITUATION
      stepHeader("05", "Current Situation: Set the Baseline"),
      bodyText("Goal: Understand the actual state of the business so your pitch is specific and credible."),
      questionItem('"How many active clients would you say you have right now?"'),
      questionItem('"What do you think your average client spends per year?"'),
      questionItem('"How booked are your devices on an average week?"'),
      questionItem('"How much of the day-to-day still depends on you personally?"'),
      questionItem('"If you stepped away for two weeks, what would break?"'),
      spacer(40),

      // 6. GOALS
      stepHeader("06", "Goals: Pull Them Forward"),
      bodyText("Goal: Get them emotionally connected to the future version of their business. This becomes your anchor during the pitch."),
      questionItem('"If everything worked the way it should, where do you want this business in 12 months?"'),
      questionItem('"How many hours a week do you actually want to be working?"'),
      questionItem('"What would it mean for you personally if this business finally ran without you being the bottleneck?"'),
      spacer(40),

      // 7. PAST
      stepHeader("07", "Past: Why Others Failed"),
      bodyText("Goal: Understand their previous experiences so you can position Luxora as the different approach."),
      questionItem('"Have you hired agencies or consultants before?"'),
      questionItem('"What did not work?"'),
      questionItem('"What do you wish they had actually fixed, but never did?"'),
      questionItem('"Do you feel like they focused on leads, or on the business itself?"'),
      spacer(40),

      // 8. DOUBT
      stepHeader("08", "Doubt: Surface Objections Early"),
      bodyText("Goal: Find the hidden belief blocking them from moving forward. Better to uncover this now than at the close."),
      questionItem('"Why do you think this has not worked yet, even though you have invested so much?"'),
      questionItem('"What do you think is actually broken underneath everything?"'),
      questionItem('"Do you believe this is something you can realistically fix on your own?"'),
      spacer(40),

      // 9. COMPARISON
      stepHeader("09", "Comparison: Eliminate Alternatives"),
      bodyText("Goal: Understand who else they are talking to and reset the comparison away from leads to real outcomes."),
      questionItem('"Are you talking to anyone else right now?"'),
      questionItem('"If someone else promised you more leads, would that actually solve the problem?"'),
      questionItem('"What would make you feel confident choosing one path and committing fully?"'),
      spacer(40),

      // 10. SUPPORT
      stepHeader("10", "Support: Match Delivery to Desire"),
      bodyText("Goal: Confirm they want real implementation support, not just a strategy PDF. This sets up the pitch perfectly."),
      questionItem('"In an ideal world, what kind of support do you want?"'),
      questionItem('"Do you want strategy only, or someone actually building this with you?"'),
      questionItem('"How important is it that your whole team gets trained, not just you?"'),
      spacer(40),

      // 11. TRUST
      stepHeader("11", "Trust: Understand Why They Showed Up"),
      bodyText("Goal: Anchor their existing belief in Luxora before you move to the pitch. This is your warm close setup."),
      questionItem('"Before we move forward: how long have you been following us?"'),
      questionItem('"What made you trust us enough to book this call?"'),

      spacer(80),
      sectionDivider(),

      // ══════════════════════════════════════════════════════════════════════
      // PRE-PITCH TRANSITION
      // ══════════════════════════════════════════════════════════════════════
      sectionTitle("STAGE 3: PRE-PITCH TRANSITION"),
      stepHeader("12", "Reframe the Problem"),
      labelText("Say this:"),
      scriptLine('"Alright. Based on everything you have shared, I want to be very direct about something."'),
      scriptLine('"This is not a marketing problem."'),
      scriptLine('"You do not have a lead issue. You have a systems and lifetime value problem. That is why every agency you have hired has failed. They poured water into a leaking ship."'),
      scriptLine('"What we do is completely different."'),
      tip("Pause here. Let that land before moving into the pitch."),

      spacer(80),
      sectionDivider(),

      // ══════════════════════════════════════════════════════════════════════
      // PITCH
      // ══════════════════════════════════════════════════════════════════════
      sectionTitle("STAGE 4: THE PITCH"),
      new Paragraph({
        children: [new TextRun({ text: "The Luxora Growth Engine: 3 Pillars", bold: true, size: 28, color: DARK_TEXT, font: "Arial" })],
        spacing: { before: 0, after: 160 }
      }),

      // PILLAR 1
      shadeBox([
        new Paragraph({
          children: [new TextRun({ text: "PILLAR 1: The Blueprint", bold: true, size: 24, color: ROSE_GOLD, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "Market Intelligence + Offer Strategy", bold: true, size: 22, color: MID_GRAY, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({
          children: [new TextRun({ text: '"Before we run a single ad, we map your entire market. Competitors, pricing gaps, offer positioning, and opportunity. Within 72 hours, you know exactly what will work before you spend a dollar."', size: 22, color: DARK_TEXT, font: "Arial", italics: true })],
          spacing: { before: 0, after: 120 },
          indent: { left: 200 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "What this includes:", bold: true, size: 22, color: DARK_TEXT, font: "Arial" })],
          spacing: { before: 80, after: 60 }
        }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Full competitor landscape analysis for your market", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Offer audit: what you should be selling and at what price", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Package and upsell architecture (using our Package and Upsell Framework)", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Customized 90-day growth roadmap with clear milestones", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Statement of Work and kickoff documentation", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        spacer(80),
        new Paragraph({
          children: [new TextRun({ text: "Check-in: ", bold: true, size: 22, color: ROSE_GOLD, font: "Arial" }), new TextRun({ text: '"Does that already feel different from what you have done before?"', size: 22, color: DARK_TEXT, font: "Arial", italics: true })],
          spacing: { before: 80, after: 0 }
        })
      ], SOFT_BLUSH),

      spacer(80),

      // PILLAR 2
      shadeBox([
        new Paragraph({
          children: [new TextRun({ text: "PILLAR 2: The Foundation", bold: true, size: 24, color: ROSE_GOLD, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "Full Acquisition System Build-Out", bold: true, size: 22, color: MID_GRAY, font: "Arial" })],
          spacing: { before: 0, after: 100 }
        }),
        new Paragraph({
          children: [new TextRun({ text: '"We do not hand you leads and disappear. We install the entire acquisition system, from ads to booking, so your team can execute without you being involved in every step."', size: 22, color: DARK_TEXT, font: "Arial", italics: true })],
          spacing: { before: 0, after: 120 },
          indent: { left: 200 }
        }),
        new Paragraph({
          children: [new TextRun({ text: "What this includes:", bold: true, size: 22, color: DARK_TEXT, font: "Arial" })],
          spacing: { before: 80, after: 60 }
        }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Meta and Google ad campaigns built and launched for your market", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "AI-powered follow-up sequences (no more leads falling through the cracks)", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "CRM build-out and optimization inside Go High Level", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Online booking and front desk workflow setup", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
        new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun({ text: "Front desk and team scripts for converting consultations", size: 22, color: DARK_TEXT, font: "Arial" })], spacing: { before: 30, after: 30 } }),
