const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
  HeadingLevel, VerticalAlign
} = require('/home/claude/.npm-global/lib/node_modules/docx');
const fs = require('fs');

const ROSE_GOLD  = "B76E79";
const SOFT_BLUSH = "F5E6E8";
const LIGHT_ROSE = "FAF0F1";
const DARK_TEXT  = "2C2C2C";
const MID_GRAY   = "666666";
const LIGHT_GRAY = "DDDDDD";
const WHITE      = "FFFFFF";
const GOLD       = "C9A96E";
const TAN        = "F7F0E8";
const DEEP_ROSE  = "9B4A55";

const bd = (color = LIGHT_GRAY) => ({ style: BorderStyle.SINGLE, size: 1, color });
const bds = (color = LIGHT_GRAY) => ({ top: bd(color), bottom: bd(color), left: bd(color), right: bd(color) });
const noBd = () => ({ style: BorderStyle.NONE, size: 0, color: "FFFFFF" });
const noBds = () => ({ top: noBd(), bottom: noBd(), left: noBd(), right: noBd() });

function spacer(pts = 80) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: pts } });
}

function divider(color = ROSE_GOLD) {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color, space: 1 } },
    spacing: { before: 40, after: 200 }
  });
}

function sectionTitle(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 28, color: ROSE_GOLD, font: "Arial" })],
    spacing: { before: 360, after: 120 }
  });
}

function stepHeader(num, title) {
  return new Paragraph({
    children: [
      new TextRun({ text: num + "  ", bold: true, size: 26, color: ROSE_GOLD, font: "Arial" }),
      new TextRun({ text: title, bold: true, size: 26, color: DARK_TEXT, font: "Arial" }),
    ],
    spacing: { before: 280, after: 80 }
  });
}

function labelText(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 20, color: MID_GRAY, font: "Arial", allCaps: true })],
    spacing: { before: 160, after: 60 }
  });
}

function scriptLine(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color: DARK_TEXT, font: "Arial", italics: true })],
    spacing: { before: 40, after: 40 },
    indent: { left: 360 }
  });
}

function tip(text) {
  return new Paragraph({
    children: [new TextRun({ text: "TIP: " + text, size: 20, color: GOLD, font: "Arial", bold: true })],
    spacing: { before: 80, after: 40 },
    indent: { left: 360 }
  });
}

function bullet(text, ref = "bullets") {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children: [new TextRun({ text, size: 22, color: DARK_TEXT, font: "Arial" })],
    spacing: { before: 40, after: 40 }
  });
}

function bodyText(text, color = MID_GRAY) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color, font: "Arial" })],
    spacing: { before: 40, after: 60 },
    indent: { left: 360 }
  });
}

function shadeBox(children, fill = SOFT_BLUSH, borderColor = ROSE_GOLD) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      borders: bds(borderColor),
      width: { size: 9360, type: WidthType.DXA },
      shading: { fill, type: ShadingType.CLEAR },
      margins: { top: 140, bottom: 140, left: 220, right: 220 },
      children
    })] })]
  });
}

function goldBox(children) {
  return shadeBox(children, TAN, GOLD);
}

function twoCol(left, right, lw = 4680, rw = 4680) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [lw, rw],
    rows: [new TableRow({ children: [
      new TableCell({ borders: noBds(), width: { size: lw, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 }, children: left }),
      new TableCell({ borders: noBds(), width: { size: rw, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 120, right: 0 }, children: right })
    ]})]
  });
}

// ── OBJECTION ROW HELPER ───────────────────────────────────────────────────
function objRow(objection, response, i) {
